func testRolloutJetStream(t *testing.T) jetstream.JetStream {
	t.Helper()
	auth := newAuthenticatedNATS(t, "gru")
	runtime, err := auth.start(t, t.Context(), natscell.Config{Cell: "gru", Embedded: &natscell.Embedded{}})
	if err != nil {
		t.Fatal(err)
	}
	return runtime.JetStream()
}

func newAuthenticatedNATS(t *testing.T, cell string, brokers ...string) *authenticatedNATS {
	t.Helper()
	a := &authenticatedNATS{root: t.TempDir(), cell: cell, brokers: slices.Clone(brokers)}
	a.tls, a.routePassword = testR3TLSMaterial(t, a.root)
	operator, err := nkeys.CreateOperator()
	if err != nil {
		t.Fatal(err)
	}
	system, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	a.account, err = nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	a.cellID, _ = a.account.PublicKey()
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	operatorJWT, err := operatorClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemJWT, err := jwt.NewAccountClaims(systemID).Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	cellClaim := jwt.NewAccountClaims(a.cellID)
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 256 << 20, DiskStorage: 8 << 30, Streams: 100, Consumer: 100}
	a.cellJWT, err = cellClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, raw string) string {
		path := filepath.Join(a.root, name)
		if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	a.operatorFile = write("operator.jwt", operatorJWT)
	a.systemFile = write("system.jwt", systemJWT)
	a.cellFile = write("cell.jwt", a.cellJWT)
	systemUser, systemCredentials := testBrokerJWTUser(t, a.root, "system.creds", system, systemID,
		[]string{"$SYS.REQ.ACCOUNT." + a.cellID + ".CLAIMS.UPDATE"}, nil)
	systemClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, systemCredentials))
	if err != nil {
		t.Fatal(err)
	}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUser) + ".>"}
	a.systemCredentials = testBrokerJWTUserWithClaim(t, a.root, "system.creds", system, systemClaim)
	public, _ := testEd25519(t, a.root, "ticket.key")
	a.ticketPrivateFile = filepath.Join(a.root, "ticket.key")
	a.ticketPublicFile = write("ticket.pub", base64.StdEncoding.EncodeToString(public))
	return a
}

func (a *authenticatedNATS) config(t *testing.T, cfg natscell.Config) natscell.Config {
	t.Helper()
	if cfg.Cell != "" && cfg.Cell != a.cell {
		t.Fatalf("fixture cell %q differs from client cell %q", a.cell, cfg.Cell)
	}
	cfg.Cell = a.cell
	if cfg.Instance == "" {
		cfg.Instance = "one"
	}
	if cfg.Replicas == 0 {
		cfg.Replicas = 1
	}
	role := cfg.ClientRole
	if role == "" {
		role = "controller"
	}
	var user nkeys.KeyPair
	var err error
	if cfg.NKeySeedFile != "" {
		seed, readErr := os.ReadFile(cfg.NKeySeedFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.FromSeed(seed)
		clear(seed)
	} else if cfg.CredentialsFile != "" {
		credentials, readErr := os.ReadFile(cfg.CredentialsFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.ParseDecoratedUserNKey(credentials)
		clear(credentials)
	} else {
		user, err = nkeys.CreateUser()
	}
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = a.cellID
	claim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(a.cell, public) + ".>"}
	switch role {
	case "controller":
		claim.Pub.Allow = natscell.ControllerPublishes(a.cell)
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Pub.Allow.Add("$JS.ACK.>")
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions(a.cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(a.cell), protocol.Broker(a.cell, "ticket", ">"), protocol.Broker(a.cell, "fence", cfg.Instance))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
	case "operator":
		claim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(a.cell)
	case "host":
		claim.Pub.Allow = jwt.StringList{protocol.AgentObservation(a.cell, public, "*")}
	default:
		t.Fatalf("unsupported authenticated fixture role %q", role)
	}
	cfg.CredentialsFile = testBrokerJWTUserWithKey(t, a.root, cfg.Instance+"-"+public+".creds", a.account, user, claim)
	cfg.NKeySeedFile = ""
	cfg.TLS = a.tls
	cfg.URL = strings.ReplaceAll(cfg.URL, "nats://", "tls://")
	if cfg.Embedded != nil {
		embedded := *cfg.Embedded
		cfg.Embedded = &embedded
		embedded.Users = nil
		embedded.TLS, embedded.RouteTLS = a.tls, a.tls
		embedded.RouteUser, embedded.RoutePasswordFile = "integration-route", a.routePassword
		embedded.OperatorJWTFile, embedded.SystemJWTFile, embedded.CellJWTFile = a.operatorFile, a.systemFile, a.cellFile
		embedded.SystemCredentialsFile, embedded.TicketPublicKeyFile = a.systemCredentials, a.ticketPublicFile
		embedded.BrokerIDs = slices.Clone(a.brokers)
		if len(embedded.BrokerIDs) == 0 {
			embedded.BrokerIDs = []string{cfg.Instance}
		}
		if embedded.StoreDir == "" {
			embedded.StoreDir = filepath.Join(a.root, cfg.Instance)
		}
		if embedded.Host == "" {
			embedded.Host = "127.0.0.1"
		}
		if embedded.Port == 0 {
			embedded.Port = reserveControllerPort(t)
		}
	}
	return cfg
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
	t.Helper()
	runtime, err := natscell.Start(ctx, a.config(t, cfg))
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if cfg.Embedded != nil {
		if err := runtime.ApplyCellClaim(ctx, 1, a.cellJWT); err != nil {
			return nil, fmt.Errorf("apply fixture claim: %w", err)
		}
		if err := runtime.Bridge().OpenUntil(1, a.cellJWT, time.Now().Add(5*time.Minute)); err != nil {
			return nil, fmt.Errorf("open fixture bridge: %w", err)
		}
	}
	return runtime, nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func OpenHostMetricStream(ctx context.Context, js jetstream.JetStream, cell string, replicas int) (*HostMetricStream, error) {
	if js == nil {
		return nil, errors.New("host metric stream requires JetStream")
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("host metric stream replica count is out of range")
	}
	subject, err := protocol.ObservabilitySubject(cell, "host-metrics")
	if err != nil {
		return nil, err
	}
	stream, err := js.CreateStream(ctx, jetstream.StreamConfig{
		Name:        HostMetricStreamName,
		Description: "Regional host metric history",
		Subjects:    []string{subject + "." + strings.ToLower(rand.Text())},
		Storage:     jetstream.FileStorage,
		Replicas:    replicas,
		Retention:   jetstream.LimitsPolicy,
		Discard:     jetstream.DiscardNew,
		MaxAge:      HistoryRetention,
		MaxBytes:    HostMetricStreamBytes,
		MaxMsgs:     -1,
		MaxMsgSize:  HostMetricBatchBytes + hostMetricHeaderBytes,
	})
	if errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
		stream, err = js.Stream(ctx, HostMetricStreamName)
	}
	if err != nil {
		return nil, fmt.Errorf("open host metric stream: %w", err)
	}
	info := stream.CachedInfo()
	if len(info.Config.Subjects) != 1 || !strings.HasPrefix(info.Config.Subjects[0], subject+".") ||
		protocol.ValidateSubjectToken(strings.TrimPrefix(info.Config.Subjects[0], subject+".")) != nil {
		return nil, errors.New("host metric stream lacks a v1 generation subject; delete and recreate it")
	}
	config := info.Config
	if config.Storage != jetstream.FileStorage || config.Replicas != replicas || config.Retention != jetstream.LimitsPolicy ||
		config.Discard != jetstream.DiscardNew || config.MaxAge != HistoryRetention || config.MaxBytes != HostMetricStreamBytes ||
		config.MaxMsgs != -1 || config.MaxMsgSize != HostMetricBatchBytes+hostMetricHeaderBytes || config.NoAck ||
		config.SubjectTransform != nil || config.Mirror != nil || len(config.Sources) != 0 || config.RePublish != nil {
		return nil, errors.New("host metric stream contract differs from v1; delete and recreate it")
	}
	// The server rejects old-generation writes even when recreation races an in-flight request.
	return &HostMetricStream{stream: stream, createdAt: info.Created, js: js, subject: info.Config.Subjects[0]}, nil
}

func (stream *HostMetricStream) info(ctx context.Context) (*jetstream.StreamInfo, error) {
	stream.streamMu.Lock()
	defer stream.streamMu.Unlock()
	info, err := stream.stream.Info(ctx)
	if err == nil && (!info.Created.Equal(stream.createdAt) || len(info.Config.Subjects) != 1 || info.Config.Subjects[0] != stream.subject) {
		return nil, errors.New("host metric stream was recreated; restart controller to reset publication and replay state")
	}
	return info, err
}

func (stream *HostMetricStream) message(ctx context.Context, sequence uint64) (*jetstream.RawStreamMsg, error) {
	stream.streamMu.Lock()
	defer stream.streamMu.Unlock()
	return stream.stream.GetMsg(ctx, sequence)
}

func (stream *HostMetricStream) Publish(ctx context.Context, batch HostMetricBatch) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	batch.At = batch.At.UTC().Truncate(HostMetricInterval)
	data, err := encodeHostMetricBatch(batch)
	if err != nil {
		return false, err
	}
	for range hostMetricPublishAttempts {
		info, err := stream.info(ctx)
		if err != nil {
			return false, err
		}
		lastSeq := info.State.LastSeq
		if info.State.Msgs > 0 {
			message, err := stream.message(ctx, lastSeq)
			if errors.Is(err, jetstream.ErrMsgNotFound) {
				continue // Retention may have expired the message after Info.
			}
			if err != nil {
				return false, err
			}
			if message.Subject != stream.subject {
				return false, errors.New("host metric publication crossed stream generation")
			}
			last, err := decodeHostMetricBatch(message.Data)
			if err != nil {
				return false, fmt.Errorf("read latest host metric batch: %w", err)
			}
			if !batch.At.After(last.At) {
				return bytes.Equal(message.Data, data), nil
			}
		}
		_, err = stream.js.Publish(ctx, stream.subject, data, jetstream.WithExpectLastSequence(lastSeq))
		if err == nil {
			return true, nil
		}
		var apiErr *jetstream.APIError
		if !errors.As(err, &apiErr) || (apiErr.ErrorCode != jetstream.JSErrCodeStreamWrongLastSequence &&
			apiErr.ErrorCode != jetstream.JSErrCodeStreamWrongLastSequenceConstant) {
			return false, err
		}
	}
	if err := ctx.Err(); err != nil {
		return false, err
	}
	return false, errors.New("host metric publish contention exceeded retry bound")
}

func (stream *HostMetricStream) Tail(ctx context.Context, history *History) error {
	stream.caughtUp.Store(false)
	defer stream.caughtUp.Store(false)
	if history == nil {
		return errors.New("host metric tail requires history")
	}
	var next uint64
	backoff := time.Second
	for ctx.Err() == nil {
		err := stream.tailHostMetricsOnce(ctx, history, &next)
		if ctx.Err() != nil {
			return ctx.Err()
		}
		slog.DebugContext(ctx, "host metric stream tail restarting", ComponentKey, "observability", "error", err)
		timer := time.NewTimer(backoff)
		select {
		case <-ctx.Done():
			timer.Stop()
			return ctx.Err()
		case <-timer.C:
		}
		backoff = min(backoff*2, 30*time.Second)
	}
	return ctx.Err()
}

func (stream *HostMetricStream) tailHostMetricsOnce(ctx context.Context, history *History, next *uint64) error {
	stream.caughtUp.Store(false)
	defer stream.caughtUp.Store(false)
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	connection := stream.js.Conn()
	statuses := connection.StatusChanged(nats.RECONNECTING, nats.DISCONNECTED, nats.CLOSED)
	defer connection.RemoveStatusListener(statuses)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(hostMetricReplayWait)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-statuses:
				stream.caughtUp.Store(false)
				cancel()
				return
			case <-ticker.C:
				checkCtx, cancelCheck := context.WithTimeout(ctx, hostMetricReplayWait)
				_, err := stream.info(checkCtx)
				cancelCheck()
				if err != nil {
					stream.caughtUp.Store(false)
					cancel()
					return
				}
			}
		}
	}()
	defer func() { cancel(); <-done }()
	info, err := stream.info(ctx)
	if err != nil {
		return err
	}
	caughtUp := info.State.LastSeq
	config := jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverAllPolicy, FilterSubjects: []string{stream.subject}}
	if *next != 0 {
		config.DeliverPolicy, config.OptStartSeq = jetstream.DeliverByStartSequencePolicy, *next
	}
	consumer, err := stream.stream.OrderedConsumer(ctx, config)
	if err != nil {
		return err
	}
	messages, err := consumer.Messages()
	if err != nil {
		return err
	}
	defer messages.Stop()
	stop := context.AfterFunc(ctx, messages.Stop)
	defer stop()
	if ctx.Err() == nil && (info.State.Msgs == 0 || *next > caughtUp) {
		stream.caughtUp.Store(true)
	}
	type replayRecord struct {
		sequence uint64
		data     []byte
	}
	// Bound buffered payloads and validate one generation per chunk, not per minute.
	pending := make([]replayRecord, 0, hostMetricReplayChunk)
	readNext := *next
	flush := func() (*jetstream.StreamInfo, error) {
		info, err := stream.info(ctx)
		if err != nil {
			return nil, err
		}
		for _, record := range pending {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			if batch, err := decodeHostMetricBatch(record.data); err == nil {
				if batch.Incomplete {
					stream.archiveIncomplete.Store(true)
				}
				history.Append(batch.At, batch.Samples)
			} else {
				stream.rejectReplayBatch(record.sequence)
			}
			*next = record.sequence + 1
		}
		clear(pending)
		pending = pending[:0]
		if ctx.Err() == nil && *next > caughtUp {
			stream.caughtUp.Store(true)
		}
		return info, nil
	}
	for {
		nextCtx, cancelNext := context.WithTimeout(ctx, hostMetricReplayWait)
		message, err := messages.Next(jetstream.NextContext(nextCtx))
		cancelNext()
		if errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
			info, err := flush()
			if err != nil {
				return err
			}
			// Retention may remove the replay target before it can be delivered.
			if ctx.Err() == nil && (info.State.Msgs == 0 || *next > info.State.LastSeq) {
				stream.caughtUp.Store(true)
			}
			continue // NextContext deadlines leave the iterator usable.
		}
		if err != nil {
			return err
		}
		if message.Subject() != stream.subject {
			return errors.New("host metric replay crossed stream generation")
		}
		metadata, err := message.Metadata()
		if err != nil {
			return err
		}
		sequence := metadata.Sequence.Stream
		if sequence < readNext {
			continue
		}
		pending = append(pending, replayRecord{sequence: sequence, data: message.Data()})
		readNext = sequence + 1
		if len(pending) == hostMetricReplayChunk || sequence >= caughtUp {
			if _, err := flush(); err != nil {
				return err
			}
		}
	}
}

